			BNode blank = VF.createBNode("b1");
			c.add(node(7), p, blank); // blank-node object
			c.add(blank, p, node(8));
			edge(c, 8, p, 9);
			for (int n = 0; n <= 9; n += 2) {
				c.add(node(n), q, VF.createLiteral(n));
			}
			c.add(node(1), q, VF.createLiteral("one"));
			c.add(node(2), q, node(5)); // q edges between nodes, for alternatives
			c.add(node(0), q, node(6));
			c.add(node(2), iri("p"), node(3), iri("g")); // a named-graph statement
			c.add(node(3), iri("p"), node(4), iri("g"));
