	/** Seeded random graphs: native-disabled and native-enabled bags and row provenance agree, one query per shape. */
	@ParameterizedTest(name = "seed {0}")
	@org.junit.jupiter.params.provider.ValueSource(longs = { 11L, 23L, 37L })
	void randomGraphsKeepTheOrdinaryBag(long seed) {
		Random random = new Random(seed);
		SailRepository random_ = new SailRepository(new LmdbStore(directory.resolve("seed" + seed).toFile(),
				new LmdbStoreConfig("spoc,posc,ospc,cspo").setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(true)));
		random_.init();
		try {
			int nodes = 150;
			IRI p = iri("p"), q = iri("q");
			try (SailRepositoryConnection c = random_.getConnection()) {
				c.begin();
				for (int i = 0; i < 5; i++) {
					int n = random.nextInt(nodes);
					c.add(node(n), p, node(n)); // self loops
				}
				for (int i = 0; i < 450; i++) {
					int from = random.nextInt(nodes), kind = random.nextInt(10);
					if (kind == 0) {
						c.add(node(from), p, VF.createLiteral("lit" + random.nextInt(30)));
					} else if (kind == 1) {
						BNode blank = VF.createBNode("b" + random.nextInt(30));
						c.add(node(from), p, blank);
						c.add(blank, p, node(random.nextInt(nodes)));
					} else {
						c.add(node(from), p, node(random.nextInt(nodes)));
					}
				}
				for (int i = 0; i < 100; i++) {
					c.add(node(random.nextInt(nodes)), q, VF.createLiteral(random.nextInt(50)));
				}
				for (int i = 0; i < 60; i++) {
					c.add(node(random.nextInt(nodes)), q, node(random.nextInt(nodes)));
				}
				c.commit();
			}
			java.util.ArrayList<String> queries = new java.util.ArrayList<>();
			queries.add("SELECT ?o WHERE { :n" + random.nextInt(nodes) + " :p+ ?o }");
			queries.add("SELECT ?s WHERE { ?s :p+ :n" + random.nextInt(nodes) + " }");
			queries.add("SELECT ?o WHERE { :n" + random.nextInt(nodes) + " :p* ?o }");
			queries.add("SELECT ?s WHERE { ?s :p* :n" + random.nextInt(nodes) + " }");
			queries.add("SELECT * WHERE { :n" + random.nextInt(nodes) + " :p* :n" + random.nextInt(nodes) + " }");
			queries.add("SELECT ?o WHERE { :n" + random.nextInt(nodes) + " (:p|:q)+ ?o }");
			queries.add("SELECT ?o WHERE { :n" + random.nextInt(nodes) + " (:p|:q)* ?o }");
			queries.add("SELECT ?s ?o WHERE { ?s :p+ ?o }");
			queries.add("SELECT ?o ?v WHERE { :n" + random.nextInt(nodes) + " :p+ ?o . ?o :q ?v }");
			queries.add("SELECT ?s ?v ?o WHERE { ?s :q ?v . ?s :p+ ?o }");
			queries.add("SELECT ?o ?v WHERE { :n" + random.nextInt(nodes) + " :p* ?o . ?o :q ?v }");
			queries.add("SELECT ?o WHERE { :absent :p* ?o }");
			for (String query : queries) {
				assertEquals(bag(random_, query, false), bag(random_, query, true), "seed " + seed + ": " + query);
				assertEquals(rowsWithProvenance(random_, query, false), rowsWithProvenance(random_, query, true),
						"seed " + seed + " provenance: " + query);
			}
		} finally {
			random_.shutDown();
		}
	}

	private record Row(Map<String, Value> values, boolean tracked, Set<String> requests, Set<String> locals,
			Map<String, Value> parameters, Map<String, Value> graphs) {
	}

	private Map<Row, Integer> rowsWithProvenance(SailRepository repo, String query, boolean nativeEngine) {
		System.setProperty(FLAG, Boolean.toString(nativeEngine));
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, PREFIX + query, null).getTupleExpr();
		TupleExpr root = parsed instanceof QueryRoot ? parsed.clone() : new QueryRoot(parsed.clone());
		Map<Row, Integer> result = new HashMap<>();
		try (SailRepositoryConnection c = repo.getConnection();
				var rows = c.getSailConnection().evaluate(root, null, EmptyBindingSet.getInstance(), true)) {
			while (rows.hasNext()) {
				BindingSet row = rows.next();
				Map<String, Value> values = new LinkedHashMap<>();
				for (String name : row.getBindingNames()) {
					values.put(name, row.getValue(name));
				}
				BindingSetOrigin origin = BindingSetOrigin.of(row);
				result.merge(new Row(Collections.unmodifiableMap(values), BindingSetOrigin.isTrackedInput(row),
						Set.copyOf(origin.requestNames()), Set.copyOf(origin.localNames()),
						Collections.unmodifiableMap(new LinkedHashMap<>(origin.retainedParametersForTransport())),
						Collections.unmodifiableMap(new LinkedHashMap<>(
								GraphFrameBindings.from(row).retainedParametersForTransport()))),
						1, Integer::sum);
			}
		}
		return result;
	}

	private Map<Map<String, Value>, Integer> bag(String query, boolean nativeEngine, Map<String, Value> input) {
		return bag(repository, query, nativeEngine, input);
	}

	private Map<Map<String, Value>, Integer> bag(SailRepository repo, String query, boolean nativeEngine) {
		return bag(repo, query, nativeEngine, null);
	}

	private Map<Map<String, Value>, Integer> bag(SailRepository repo, String query, boolean nativeEngine,
			Map<String, Value> input) {
		System.setProperty(FLAG, Boolean.toString(nativeEngine));
		Map<Map<String, Value>, Integer> result = new HashMap<>();
		try (SailRepositoryConnection c = repo.getConnection()) {
			TupleQuery tq = c.prepareTupleQuery(PREFIX + query);
			if (input != null) {
				input.forEach(tq::setBinding);
			}
			try (TupleQueryResult rows = tq.evaluate()) {
				while (rows.hasNext()) {
					BindingSet row = rows.next();
					Map<String, Value> values = new HashMap<>();
					row.forEach(b -> values.put(b.getName(), b.getValue()));
					result.merge(values, 1, Integer::sum);
				}
			}
		}
		return result;
	}

	private String explain(String query, Map<String, Value> input) {
		System.setProperty(FLAG, "true");
		try (SailRepositoryConnection c = repository.getConnection()) {
			TupleQuery tq = c.prepareTupleQuery(PREFIX + query);
			if (input != null) {
				input.forEach(tq::setBinding);
			}
			return tq.explain(Explanation.Level.Telemetry).toString();
		}
	}
